/* @lc app=leetcode id=3509 lang=kotlin */ class Solution { fun maxProduct(nums: IntArray, k: Int, limit: Int): Int = nums.fold(HashSet<Long>()) { st, x -> HashSet(st).also { nw -> st.forEach { e -> (e % 2).toInt().let { p -> (e / 2).let { rest -> (rest % 5001).toInt().let { pr -> (rest / 5001 - 2000).toInt().let { sm -> if (pr.toLong() * x <= limit) nw.add((((sm + (if (p == 0) x else -x) + 2000).toLong() * 5001 + pr * x) * 2) + (1 - p)) } } } } }.let { if (x <= limit) nw.add(((x + 2000).toLong() * 5001 + x) * 2 + 1) } } }.filter { e -> (e / 2 / 5001 - 2000).toInt() == k }.maxOfOrNull { ((it / 2) % 5001).toInt() } ?: -1 }